package com.oms.order.service;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.*;

/** Platform writes are explicit, durable, and never blindly retried after an uncertain reply. */
@Service public class ExchangeExecution {
    @Resource OrderCatalog carrierCatalog;
    @Resource private ExchangeControlService controls;
    @Resource private ExchangeContinuationService continuations;
    @Resource private OrderRepository repository;
    @Resource private ExchangeService exchanges;
    @Resource private ExchangeFulfillment fulfillment;
    @Resource private ExchangeReturnClient returns;
    @Resource private ExchangeOperationJournal journal;
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    public Map<String,Object> reasons(String company,long id){Map<String,Object> e=exchanges.row(company,id,false);require(number(e,"fulfillment_hold")==0&&!ExchangeControlService.terminal(e),"换货已挂起、正在截单或已结束");require("PLATFORM".equals(text(e,"source_kind")),"协商换品没有平台拒绝原因");return exchanges.call(company,number(e,"channel_id"),"REASONS",map("dispute_id",e.get("dispute_id"),"fields","reason_id,reason_text"));}
    public Map<String,Object> request(String company,long id,Map<String,Object> input,String actor){String action=text(input,"operation"),reason=text(input,"reason").trim();require(Arrays.asList("AGREE","REFUSE","RECEIVED","CONSIGN").contains(action),"换货执行动作无效");require(!reason.isEmpty()&&reason.length()<=500,"请填写处理依据");Map<String,Object> prior=exchanges.row(company,id,false);Map<String,Object> args=map("dispute_id",prior.get("dispute_id"),"fields","dispute_id,bizorder_id,modified,status");
        if("REFUSE".equals(action)){String selected=text(input,"seller_refuse_reason_id");boolean valid=false;for(Object item:(List<?>)reasons(company,id).get("reasons"))if(selected.equals(text(object(item),"reason_id")))valid=true;require(valid,"请选择平台当前允许的拒绝原因");args.put("seller_refuse_reason_id",selected);args.put("leave_message",reason);}
        tx().execute(s->{Map<String,Object> e=exchanges.row(company,id,true);require(number(e,"control_version")==number(input,"control_version"),"申请已有新版本，请刷新");require(ExchangeRounds.numberOf(e)==1||"CONSIGN".equals(action),"继续换出复用原平台同意和收货结果，仅允许回传实际换出物流");require("PLATFORM".equals(text(e,"source_kind"))&&e.get("linked_exchange_id")==null,"协商或已关联申请不提交平台换货接口，请核对关联处理单");require(Arrays.asList("NONE","FAILED").contains(text(e,"platform_operation")),"原平台操作尚未核对，请勿重复提交");require(e.get("lease_until")==null||time(text(e,"lease_until")).isBefore(LocalDateTime.now()),"任务正在执行，请稍后刷新");require(number(e,"speed_exchange")!=1,"极速换货请转平台处理");Map<String,Object> config=repository.db().query("SELECT write_enabled FROM oms_exchange_config WHERE company_code=? AND channel_id=?",ROW,company,e.get("channel_id")).stream().findFirst().orElseThrow(()->new IllegalArgumentException("店铺换货接入未配置"));require(number(config,"write_enabled")==1,"店铺尚未允许换货平台写操作");
            if(!"REFUSE".equals(action))ExchangeFulfillment.planUnchanged(e);if("AGREE".equals(action)){require(Arrays.asList("APPROVED","WAIT_STOCK").contains(text(e,"state")),"请先审核普通换货方案");args.put("address_id",e.get("platform_address_id"));args.put("leave_message",reason);}if("RECEIVED".equals(action))require("PASSED".equals(text(e,"return_qc")),"退回商品尚未实际入库并完成验收");if("CONSIGN".equals(action))args.putAll(consignment(company,e));
            Map<String,Object> request=map("operation",action,"args",args,"actor",actor,"reason",reason,"flow_operation_id",input.get("flow_operation_id"),"automatic_policy_revision",input.get("automatic_policy_revision"));if(number(input,"flow_operation_id")>0){require(journal!=null&&ExchangeFlowPolicy.ACTOR.equals(actor),"自动平台操作上下文无效");journal.authorize(company,e,request);}repository.db().update("UPDATE oms_exchange SET platform_operation='PENDING',platform_request=?,platform_operation_version=approved_version,platform_error='',next_attempt=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",encode(request),company,id);exchanges.event(company,id,"PLATFORM_REQUEST",text(e,"state"),number(e,"control_version")+1,"已登记平台"+action+"请求；等待执行结果",request,actor);return null;});return exchanges.detail(company,id);}
    private Map<String,Object> consignment(String company,Map<String,Object> e){require(e.get("fulfillment_order_id")!=null,"尚未生成换出履约");long child=number(e,"fulfillment_order_id");List<Map<String,Object>> packages=repository.db().query("SELECT p.* FROM oms_order_shipment_package p JOIN oms_order_shipment s ON s.company_code=p.company_code AND s.id=p.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE' ORDER BY p.id",ROW,company,e.get("id"));long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE'",Long.class,company,e.get("id"));require(shipped==number(e,"requested_quantity"),"换出商品尚未全部实际出库");require(packages.stream().mapToLong(p->number(p,"quantity")).sum()==shipped,"换出商品还有未关联运单的数量");Set<String> tracks=new HashSet<>();for(Map<String,Object> p:packages)tracks.add(text(p,"carrier_code")+"/"+text(p,"express_code"));require(tracks.size()==1,"平台单次换货发货接口仅能提交一组物流，请人工核对多运单在平台的处理方式");Map<String,Object> first=packages.get(0);long standard=number(first,"standard_id");if(standard==0){List<Long> ids=repository.db().queryForList("SELECT id FROM oms_carrier_standard WHERE company_code=? AND standard_code=?",Long.class,company,first.get("carrier_code"));require(ids.size()==1,"换出包裹实际快递尚未识别");standard=ids.get(0);}Map<String,Object> shop=carrierCatalog.channels(company).stream().filter(c->number(c,"channel_id")==number(e,"channel_id")).findFirst().orElseThrow(()->new IllegalArgumentException("换货店铺不属于当前公司"));Map<String,Object> ctx=map("system_type","CHANNEL","provider",SharedCarrierService.platform(text(shop,"channel_type")),"connection_id",text(shop,"connection_id"),"shop_id",text(e,"channel_id"),"purpose","CHANNEL_EXCHANGE_LOGISTICS","direction","OUT","standard_id",standard);Map<String,Object> converted=new SharedCarrierService(repository).freeze(company,"EXCHANGE_CONSIGN_"+e.get("id")+"_"+ExchangeRounds.numberOf(e),ctx,"换货发货回传");require(Boolean.TRUE.equals(converted.get("available")),text(converted,"message"));return map("logistics_type","200","logistics_company_name",converted.get("external_name"),"logistics_no",first.get("express_code"));}
    public Map<String,Object> reconcile(String company,long id){repository.db().update("UPDATE oms_exchange SET next_attempt=NOW() WHERE company_code=? AND id=? AND platform_operation IN ('UNKNOWN','SENDING')",company,id);process(company,id);return exchanges.detail(company,id);}
    public Map<String,Object> advance(String company,long id,Map<String,Object> input,String actor){tx().execute(s->{Map<String,Object> e=exchanges.row(company,id,true);require(number(e,"control_version")==number(input,"control_version"),"申请已变化，请刷新");ExchangeFulfillment.planUnchanged(e);require(!Arrays.asList("REJECTED","CANCELED","COMPLETED").contains(text(e,"state")),"当前申请已结束");repository.db().update("UPDATE oms_exchange SET next_attempt=NOW() WHERE company_code=? AND id=?",company,id);return null;});process(company,id);return exchanges.detail(company,id);}
    public Map<String,Object> qc(String company,long id,Map<String,Object> input,String actor){
        Map<String,Object> prior=exchanges.row(company,id,false);require(!ExchangeFulfillment.unshipped(prior)&&prior.get("linked_exchange_id")==null,"当前申请无需单独退回验收");require(ExchangeRounds.numberOf(prior)==1,"继续换出复用原退回验收，不可改写；有争议请挂起核对");
        Map<String,Object> received=data(returns.detail(company,id,SecurityConstants.INNER));String why=text(input,"reason").trim(),decision=text(input,"decision").isEmpty()?"PASSED":text(input,"decision"),issue=text(input,"issue_type"),evidence=text(input,"evidence");
        require(!why.isEmpty()&&why.length()<=500&&evidence.length()<=2000,"请填写退回验收依据，凭证最多2000字");require(Arrays.asList("PASSED","ALLOW_EXCHANGE","WAIT_SUPPLEMENT","WAREHOUSE_REVIEW","BUYER_CONTACT","HOLD").contains(decision),"验收处理动作无效");require(Arrays.asList("","SHORT","EXCESS","WRONG_ITEM","DAMAGED","MISSING_PARTS","POSTING").contains(issue),"退回差异类型无效");boolean passed=Arrays.asList("PASSED","ALLOW_EXCHANGE").contains(decision);
        tx().execute(s->{Map<String,Object> e=exchanges.row(company,id,true);require(number(e,"control_version")==number(input,"control_version"),"申请已变化，请刷新");require(!Arrays.asList("COMPLETED","CANCELED","CLOSED","REJECTED").contains(text(e,"state"))&&e.get("fulfillment_line_id")==null,"已结束或已进入换出履约，不能改写退回验收");require("NONE".equals(text(e,"platform_operation")),"平台操作尚未核对，请先确认原操作");
            if(passed){ExchangeFulfillment.planUnchanged(e);require(number(received,"posted_quantity")==number(e,"requested_quantity")&&"COMPLETED".equals(text(received,"receipt_state")),"退回数量尚未完整记账，不能确认验收");require(!"ISSUE".equals(text(e,"return_qc"))||"ALLOW_EXCHANGE".equals(decision),"存在差异，请明确选择差异核对后继续换货并填写依据");}
            else require(!issue.isEmpty(),"请选择退回差异类型");
            String state=passed?"PASSED":"ISSUE";Map<String,Object> review=map("decision",decision,"issue_type",issue,"reason",why,"evidence",evidence,"actor",actor,"at",LocalDateTime.now().format(TIME));
            repository.db().update("UPDATE oms_exchange SET return_qc=?,return_qc_reason=?,return_review=?,return_result=?,problem_codes=IF(?,'RETURN_REVIEW',IF(problem_codes='RETURN_REVIEW','',problem_codes)),problem_message=IF(?,? ,IF(problem_codes='','',problem_message)),control_version=control_version+1,next_attempt=NOW() WHERE company_code=? AND id=?",state,why,encode(review),encode(returnSnapshot(received)),!passed,!passed,why,company,id);
            exchanges.event(company,id,"RETURN_QC",text(e,"state"),number(e,"control_version")+1,passed?"退回验收已确认；不重复增加库存":"退回差异已登记，暂缓换出；实收与记账事实保留",review,actor);return null;
        });return exchanges.detail(company,id);
    }
    public void pollCompany(String company){for(Long id:repository.db().queryForList("SELECT id FROM oms_exchange WHERE company_code=? AND next_attempt<=NOW() AND state NOT IN ('COMPLETED','CANCELED','CLOSED','REJECTED') AND NOT EXISTS(SELECT 1 FROM oms_exchange_flow_task f WHERE f.company_code=oms_exchange.company_code AND f.exchange_id=oms_exchange.id) AND (lease_until IS NULL OR lease_until<NOW()) ORDER BY next_attempt,id LIMIT 10",Long.class,company))process(company,id);}
    private void failure(String company,long id,String code,String message){repository.db().update("UPDATE oms_exchange SET state='BLOCKED',problem_codes=?,last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND id=?",code,message.substring(0,Math.min(500,message.length())),company,id);}
    void process(String company,long id){Map<String,Object> before=exchanges.row(company,id,false);if(number(before,"fulfillment_hold")==1){if(controls!=null)controls.process(company,id);return;}if(ExchangeControlService.terminal(before))return;String lease=token();if(repository.db().update("UPDATE oms_exchange SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,company,id)!=1)return;
        try{Map<String,Object> e=exchanges.row(company,id,false);if(ExchangeRounds.numberOf(e)>1&&"NONE".equals(text(e,"platform_operation"))){continuations.guardExecution(company,id);if(e.get("fulfillment_line_id")==null){if(fulfillment.reserve(company,id))fulfillment.materialize(company,id);repository.db().update("UPDATE oms_exchange SET next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",company,id);return;}}if("INTERNAL".equals(text(e,"source_kind"))&&!ExchangeFulfillment.unshipped(e)){internalReturn(company,id,e);return;}if(ExchangeFulfillment.unshipped(e)){fulfillment.internal(company,id);repository.db().update("UPDATE oms_exchange SET next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",company,id);return;}
            String pending=text(e,"platform_operation");Map<String,Object> operation=e.get("platform_request")==null?Collections.emptyMap():object(e.get("platform_request"));
            if(!"NONE".equals(pending)&&!"FAILED".equals(pending)){
                Map<String,Object> fresh=exchanges.call(company,number(e,"channel_id"),"DETAIL",map("dispute_id",e.get("dispute_id"),"fields",ExchangeService.FIELDS));Map<String,Object> payload=object(fresh.get("exchange"));require(text(e,"dispute_id").equals(text(payload,"dispute_id")),"平台查询返回申请身份不一致");new PlatformExchangeService(repository,exchanges).ingest(company,number(e,"channel_id"),payload,"执行前核对");e=exchanges.row(company,id,false);String action=text(operation,"operation");
                if(confirmed(action,text(e,"platform_status"))){complete(company,id,action);return;}
                if(Arrays.asList("UNKNOWN","SENDING").contains(pending)){repository.db().update("UPDATE oms_exchange SET platform_operation='UNKNOWN' WHERE company_code=? AND id=?",company,id);failure(company,id,"PLATFORM_UNKNOWN","原平台请求尚未查到可确认结果；保留原请求，不会重复提交");return;}
                if(journal!=null)journal.authorize(company,e,operation);require(expected(action).equals(text(e,"platform_status")),"平台当前状态不允许执行原请求，请人工核对");if(!"REFUSE".equals(action))ExchangeFulfillment.planUnchanged(e);
                require(!text(payload,"operation_contraint").contains("refund_onweb"),"平台要求在网页处理此申请，请人工核对");
                if("AGREE".equals(action)){if(e.get("platform_deadline")!=null)require(time(text(e,"platform_deadline")).isAfter(LocalDateTime.now()),"平台处理期限已到，请立即核对平台状态");if(!fulfillment.reserve(company,id)){repository.db().update("UPDATE oms_exchange SET platform_operation='STOCK_WAIT',next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",company,id);return;}}
                // The intent is committed before crossing the platform boundary. Expired SENDING means query only.
                require(repository.db().update("UPDATE oms_exchange SET platform_operation='SENDING' WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW() AND platform_operation IN ('PENDING','STOCK_WAIT')",company,id,lease)==1,"换货执行租约已失效");
                if(journal!=null)journal.recorded(company,operation,"SENDING","原平台命令已落地，开始提交",null);boolean acknowledged=false;try{exchanges.call(company,number(e,"channel_id"),action,object(operation.get("args")));acknowledged=true;if(journal!=null)journal.recorded(company,operation,"UNKNOWN","接口已响应，等待查询原申请确认结果",null);repository.db().update("UPDATE oms_exchange SET platform_operation='UNKNOWN',next_attempt=NOW() WHERE company_code=? AND id=?",company,id);Map<String,Object> check=exchanges.call(company,number(e,"channel_id"),"DETAIL",map("dispute_id",e.get("dispute_id"),"fields",ExchangeService.FIELDS));new PlatformExchangeService(repository,exchanges).ingest(company,number(e,"channel_id"),object(check.get("exchange")),"平台操作核对");Map<String,Object> now=exchanges.row(company,id,false);if(confirmed(action,text(now,"platform_status")))complete(company,id,action);else failure(company,id,"PLATFORM_UNKNOWN","平台已响应，查询尚未确认目标状态；等待核对原请求");}
                catch(PlatformFailure ex){if(journal!=null)journal.recorded(company,operation,ex.unknown||acknowledged?"UNKNOWN":"FAILED",ex.getMessage(),null);repository.db().update("UPDATE oms_exchange SET platform_operation=?,platform_error=? WHERE company_code=? AND id=?",ex.unknown||acknowledged?"UNKNOWN":"FAILED",ex.code,company,id);failure(company,id,ex.unknown||acknowledged?"PLATFORM_UNKNOWN":"PLATFORM_FAILED",ex.getMessage());}return;
            }
            if(e.get("approved_version")==null)return;ExchangeFulfillment.planUnchanged(e);
            if(ExchangeRounds.numberOf(e)==1&&Arrays.asList("2","3","12").contains(text(e,"platform_status"))){Map<String,Object> task=data(returns.prepare(company,id,map("exchange_sn",e.get("exchange_sn"),"store_code",e.get("return_store"),"return_basis",object(e.get("approved_snapshot")).get("return_basis"),"sender",object(e.get("approved_snapshot")).get("replacement_recipient"),"sku_sn",e.get("original_sku"),"quantity",e.get("requested_quantity"),"platform_tid",e.get("platform_tid"),"order_sn",repository.db().queryForObject("SELECT order_sn FROM oms_order WHERE company_code=? AND id=?",String.class,company,e.get("order_id"))),SecurityConstants.INNER));repository.db().update("UPDATE oms_exchange SET return_sn=?,return_result=?,stage=?,state=IF(state='APPROVED','PROCESSING',state),next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",task.get("return_sn"),encode(task),number(task,"posted_quantity")==number(e,"requested_quantity")?"RETURN_QC":"WAIT_RETURN",company,id);
                if("PASSED".equals(text(e,"return_qc"))&&"12".equals(text(e,"platform_status"))){if(e.get("fulfillment_order_id")!=null)repository.db().update("UPDATE oms_exchange SET stage='REPLACEMENT',state='PROCESSING' WHERE company_code=? AND id=?",company,id);else if(fulfillment.reserve(company,id))fulfillment.materialize(company,id);}return;}
            if(e.get("fulfillment_order_id")!=null)repository.db().update("UPDATE oms_exchange SET stage='REPLACEMENT',next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",company,id);
        }catch(RuntimeException e){Map<String,Object> now=exchanges.row(company,id,false);Map<String,Object> command=now.get("platform_request")==null?Collections.emptyMap():object(now.get("platform_request"));if(journal!=null&&number(command,"flow_operation_id")>0){boolean unknown=Arrays.asList("SENDING","UNKNOWN").contains(text(now,"platform_operation"));journal.recorded(company,command,unknown?"UNKNOWN":"FAILED",e.getMessage()==null?"原操作结果待核对":e.getMessage(),null);repository.db().update("UPDATE oms_exchange SET platform_operation=? WHERE company_code=? AND id=?",unknown?"UNKNOWN":"FAILED",company,id);}String message=e instanceof IllegalArgumentException||e instanceof PlatformFailure?e.getMessage():"关联服务暂未完成，请核对原执行记录";if(message==null)message="执行未完成";failure(company,id,"EXECUTION_REVIEW",message);}
        finally{repository.db().update("UPDATE oms_exchange SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",company,id,lease);}}
    private void internalReturn(String company,long id,Map<String,Object> e){
        if(e.get("approved_version")==null)return;ExchangeFulfillment.planUnchanged(e);
        if(e.get("fulfillment_line_id")!=null){
            long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id WHERE s.company_code=? AND s.exchange_id=?",Long.class,company,id);
            long packed=repository.db().queryForObject("SELECT COALESCE(SUM(p.quantity),0) FROM oms_order_shipment_package p JOIN oms_order_shipment s ON s.company_code=p.company_code AND s.id=p.shipment_id WHERE s.company_code=? AND s.exchange_id=?",Long.class,company,id);
            if(shipped==number(e,"requested_quantity")&&packed==shipped){repository.db().update("UPDATE oms_exchange SET state='COMPLETED',stage='FINISHED',next_attempt=NULL,control_version=control_version+1 WHERE company_code=? AND id=?",company,id);repository.db().update("UPDATE oms_exchange_round SET state='COMPLETED' WHERE company_code=? AND exchange_id=? AND round_no=?",company,id,ExchangeRounds.numberOf(e));exchanges.event(company,id,"INTERNAL_COMPLETED","COMPLETED",number(e,"control_version")+1,"协商售后换货退回验收及换出完成；未调用平台换货接口",map("shipped_quantity",shipped,"packaged_quantity",packed),"履约核对");}else repository.db().update("UPDATE oms_exchange SET next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",company,id);return;
        }
        if((e.get("stock_request")==null||"WAIT_STOCK".equals(text(e,"state")))&&!fulfillment.reserve(company,id))return;
        Map<String,Object> task=data(returns.prepare(company,id,map("exchange_sn",e.get("exchange_sn"),"store_code",e.get("return_store"),"return_basis",object(e.get("approved_snapshot")).get("return_basis"),"sender",object(e.get("approved_snapshot")).get("replacement_recipient"),"sku_sn",e.get("original_sku"),"quantity",e.get("requested_quantity"),"platform_tid",e.get("platform_tid"),"order_sn",repository.db().queryForObject("SELECT order_sn FROM oms_order WHERE company_code=? AND id=?",String.class,company,e.get("order_id"))),SecurityConstants.INNER));
        repository.db().update("UPDATE oms_exchange SET return_sn=?,return_result=?,stage=?,state=IF(state='APPROVED','PROCESSING',state),next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",task.get("return_sn"),encode(task),number(task,"posted_quantity")==number(e,"requested_quantity")?"RETURN_QC":"WAIT_RETURN",company,id);
        if("PASSED".equals(text(e,"return_qc"))&&number(task,"posted_quantity")==number(e,"requested_quantity")&&"COMPLETED".equals(text(task,"receipt_state"))&&fulfillment.reserve(company,id))fulfillment.materialize(company,id);
    }
    private String expected(String action){return "AGREE".equals(action)||"REFUSE".equals(action)?"1":"RECEIVED".equals(action)?"3":"12";}
    private boolean confirmed(String action,String state){return "AGREE".equals(action)?Arrays.asList("2","3","12","13","5").contains(state):"REFUSE".equals(action)?"4".equals(state):"RECEIVED".equals(action)?Arrays.asList("12","13","5").contains(state):Arrays.asList("13","5").contains(state);}
    private void complete(String company,long id,String action){if("REFUSE".equals(action))fulfillment.release(company,id);Map<String,Object> e=exchanges.row(company,id,false);Map<String,Object> command=e.get("platform_request")==null?Collections.emptyMap():object(e.get("platform_request"));if(journal!=null)journal.recorded(company,command,"SUCCESS","平台原操作已通过状态查询确认",map("platform_status",e.get("platform_status")));boolean awaitPlatform="CONSIGN".equals(action)&&number(command,"flow_operation_id")>0&&!"5".equals(text(e,"platform_status"));if("CONSIGN".equals(action))repository.db().update("UPDATE oms_exchange_round SET state='COMPLETED' WHERE company_code=? AND exchange_id=? AND round_no=?",company,id,ExchangeRounds.numberOf(e));String state="REFUSE".equals(action)?"REJECTED":"CONSIGN".equals(action)&&!awaitPlatform?"COMPLETED":"PROCESSING",stage=awaitPlatform?"PLATFORM_CONFIRMATION":"REFUSE".equals(action)||"CONSIGN".equals(action)?"FINISHED":"AGREE".equals(action)?"WAIT_RETURN":"REPLACEMENT";repository.db().update("UPDATE oms_exchange SET platform_operation='NONE',platform_error='',state=?,stage=?,problem_codes='',problem_message='',last_error='',next_attempt=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",state,stage,company,id);exchanges.event(company,id,"PLATFORM_CONFIRMED",state,number(e,"control_version")+1,"平台"+action+"已通过查询确认",map("platform_status",e.get("platform_status")),"平台结果核对");}
}
